import{_ as e,o as a,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Lembrar configuração de múltiplos monitores","description":"","frontmatter":{"title":"Lembrar configuração de múltiplos monitores","id":"eproc-lembrar-multiplos-monitores","plataforma":"eproc","grupo":"Menu superior","plano":"free","desde":"1.7.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-lembrar-multiplos-monitores"}]]},"headers":[],"relativePath":"funcionalidades/eproc-lembrar-multiplos-monitores.md","filePath":"funcionalidades/eproc-lembrar-multiplos-monitores.md"}'),i={name:"funcionalidades/eproc-lembrar-multiplos-monitores.md"};function t(n,o,l,u,c,d){return a(),r("div",null,o[0]||(o[0]=[s('<h1 id="lembrar-configuracao-de-multiplos-monitores" tabindex="-1">Lembrar configuração de múltiplos monitores <a class="header-anchor" href="#lembrar-configuracao-de-multiplos-monitores" aria-label="Permalink to &quot;Lembrar configuração de múltiplos monitores&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Nas configurações do eproc você pode informar que usa mais de um monitor e escolher em que posição da tela os documentos devem abrir. O eproc perde esse ajuste com frequência. Este recurso memoriza a quantidade de monitores e a posição da janela de documentos e os restaura quando o eproc os esquece.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><ul><li><strong>eproc</strong>, tela de configurações do usuário (campo &quot;Quantidade de monitores&quot; e link &quot;Configurar abertura de documentos&quot;).</li><li><strong>eproc</strong>, menu do usuário: item <strong>Restaurar configuração de monitores</strong>, logo abaixo de &quot;Configurações&quot;.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>No eproc, abra as configurações do usuário e escolha a quantidade de monitores. O eploc avisa, com um balão, que memorizou a configuração.</li><li>Com &quot;Múltiplos monitores&quot;, clique em &quot;Configurar abertura de documentos&quot;, posicione a janela que o eproc abre onde quer que os documentos apareçam e salve. O eploc memoriza também essa posição.</li><li>Se o eproc esquecer a configuração, basta abrir a tela de configurações: com o campo vazio, o eploc volta a preenchê-lo sozinho. Para a posição da janela, aparece o botão <strong>Restaurar posição da janela de documentos</strong>: um clique nele reabre a janela do eproc já no lugar memorizado e a salva.</li><li>A qualquer momento, use <strong>Restaurar configuração de monitores</strong> no menu do usuário para refazer a configuração sem sair da página em que está.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A configuração fica guardada só neste computador, porque depende dos monitores ligados a ele. Ela não vai para outros computadores nem para o backup.</li><li>O navegador só deixa abrir janelas a partir de um clique. Por isso a posição da janela é restaurada pelo botão, e não automaticamente.</li><li>Se a restauração sem sair da página não funcionar, o eploc avisa. Clique de novo em &quot;Restaurar configuração de monitores&quot; para refazê-la pela tela de configurações.</li></ul>',11)]))}const f=e(i,[["render",t]]);export{p as __pageData,f as default};
